function nma_seo($page,$tracks){$s=' | Neomoov Academy';$d='Sept modules avec quiz et attestation de suivi, huit fiches pratiques et l’application Neomoov Booster, pour chauffeurs taxi et VTC à Montréal.';$m=array(''=>array('Neomoov Chauffeur Pro — formation pratique taxi et VTC à Montréal'.$s,$d,false),'inscription'=>array('Créer mon espace gratuit'.$s,'Compte gratuit : Neomoov Booster, bilans de journée et fiches pratiques imprimables pour chauffeurs taxi et VTC.',false),'membre'=>array('Mon espace'.$s,$d,true),'formation'=>array('Ma formation Neomoov Chauffeur Pro'.$s,$d,true),'booster'=>array('Neomoov Booster : bilan de journée et vérification du véhicule'.$s,'L’application de la formation Neomoov Chauffeur Pro : recette par heure et par kilomètre, fiche de vérification avant départ et plan d’amélioration du véhicule. Gratuit, à utiliser à l’arrêt.',false),'attestation'=>array('Vérifier une attestation Neomoov Chauffeur Pro'.$s,'Vérifiez une attestation de suivi Neomoov Chauffeur Pro délivrée par Neomoov Academy à partir de son code.',true),'ressources'=>array('Fiches pratiques gratuites pour chauffeurs taxi et VTC'.$s,'Huit fiches à imprimer : bilan de journée, kit du chauffeur, démarches au Québec, prise en charge, réclamation, plan sur 30 jours.',false),'passagers'=>array('Guide passagers : un trajet plus simple'.$s,'Conseils pour préparer une prise en charge claire, voyager sereinement et signaler un problème utilement.',false),'confidentialite'=>array('Vos données'.$s,'Comment Neomoov Academy utilise et protège les données de votre compte, de vos bilans et de vos achats.',false));if(isset($tracks[$page]))return array($tracks[$page][1].' — Neomoov Chauffeur Pro'.$s,$tracks[$page][2],false);return $m[$page]??$m[''];}
function nma_modules(){return array('Votre entreprise de chauffeur, en règle'=>'Statut, inscriptions TPS et TVQ, facturation obligatoire, documents à bord et vérification sommaire du véhicule au début de chaque journée (article 55 de la Loi).','Votre journée et chaque prise en charge'=>'Temps réel, choix des courses, rencontre réussie, zones de l’aéroport, hiver et fatigue.','Votre rentabilité réelle et le choix du véhicule'=>'Prix client, recette et versement, tous les coûts, indicateurs de la semaine ; électrique ou essence.','L’expérience client et le kit du bon chauffeur'=>'Habitacle, kit recommandé par le fondateur, accueil, conduite souple, accessibilité et objets oubliés.','Prévenir les risques et gérer les incidents'=>'Reconnaissance mutuelle, nuit, désescalade, dossier factuel et caméra de bord encadrée.','Outils numériques, paiements et litiges'=>'Téléphone au volant, communications masquées, reçus, rapprochement hebdomadaire et contestation efficace.','Une activité durable et une clientèle fidèle'=>'Segments, clientèle directe dans les règles, fidélisation, santé, plan de 30 jours et parcours pour rejoindre Neomoov.');}
/* Photo d'en-tête : version WebP en plusieurs tailles (média academy-hero-webp), sinon l'image d'origine. */
function nma_hero_img(){$alt='Chauffeur dans un habitacle soigné, véhicule à l’arrêt';$p=get_page_by_title('academy-hero-webp',OBJECT,'attachment');if($p){$img=wp_get_attachment_image($p->ID,'large',false,array('alt'=>$alt,'sizes'=>'(max-width: 640px) 90vw, 560px','fetchpriority'=>'high','loading'=>'eager','decoding'=>'async'));if($img)return $img;}$u=nma_image('hero-chauffeur');return $u?'<img src="'.esc_url($u).'" alt="'.esc_attr($alt).'">':'';}
function nma_url($page=''){return home_url('/academy/'.ltrim($page,'/'));}
function nma_e($s){return esc_html($s);}
function nma_image($name){$p=get_page_by_title($name,OBJECT,'attachment');return $p?wp_get_attachment_url($p->ID):'';}
function nma_opts(){return (array)get_option('nma_settings',array());}
function nma_provider($o=null){$o=$o===null?nma_opts():$o;return in_array($o['provider']??'',array('stripe','square_manual','square_api'),true)?$o['provider']:'';}
function nma_https_url($url){$p=wp_parse_url($url);return is_array($p)&&($p['scheme']??'')==='https'&&!empty($p['host'])&&empty($p['user'])&&empty($p['pass'])&&(!isset($p['port'])||(int)$p['port']===443);}
function nma_square_url($url){return nma_https_url($url)&&in_array(strtolower((string)wp_parse_url($url,PHP_URL_HOST)),array('square.link','checkout.square.site'),true)&&trim((string)wp_parse_url($url,PHP_URL_PATH),'/')!=='';}
function nma_money_cents($value){$value=str_replace(',','.',trim((string)$value));if(!preg_match('/^\d{1,6}(?:\.\d{1,2})?$/D',$value))return 0;$parts=explode('.',$value,2);return (int)$parts[0]*100+(int)str_pad($parts[1]??'',2,'0');}
function nma_money($cents){return number_format(((int)$cents)/100,2,',',' ').' $ CA';}
function nma_stripe_credential_valid($key,$value){
 if(!is_string($value))return false;
 $patterns=array('stripe_key'=>'/^sk_(test|live)_[A-Za-z0-9]{16,}$/D','stripe_price'=>'/^price_[A-Za-z0-9]+$/D','stripe_hook'=>'/^whsec_[A-Za-z0-9]+$/D');
 return isset($patterns[$key])&&preg_match($patterns[$key],$value)===1;
}
function nma_clean_stripe_credentials($o){foreach(array('stripe_key','stripe_price','stripe_hook')as$k)if(isset($o[$k])&&!nma_stripe_credential_valid($k,$o[$k]))unset($o[$k]);return $o;}
function nma_config_ready($o){
 if(!nma_https_url($o['terms']??''))return false;
 if(nma_provider($o)==='stripe')return nma_stripe_credential_valid('stripe_key',$o['stripe_key']??'')&&nma_stripe_credential_valid('stripe_price',$o['stripe_price']??'')&&nma_stripe_credential_valid('stripe_hook',$o['stripe_hook']??'');
 if(nma_provider($o)==='square_api')return function_exists('nmsa_config_ready')&&nmsa_config_ready($o);
 if(nma_provider($o)!=='square_manual')return false;
 return nma_square_url($o['square_url']??'')&&(int)($o['square_price_cents']??0)>0&&(int)($o['square_total_cents']??0)>=(int)$o['square_price_cents']&&trim($o['square_tax_text']??'')!==''&&trim($o['square_access_delay']??'')!=='';
}
function nma_calendar_access_end($start){$date=(new DateTimeImmutable('@'.(int)$start))->setTimezone(wp_timezone());$year=(int)$date->format('Y')+1;$month=(int)$date->format('n');$last=(int)$date->setDate($year,$month,1)->format('t');return $date->setDate($year,$month,min((int)$date->format('j'),$last))->getTimestamp();}
function nma_has_access($uid){$until=(int)get_user_meta($uid,'nma_access_until',true);return get_user_meta($uid,'nma_paid',true)==='yes'&&(get_user_meta($uid,'nma_payment_provider',true)!=='square_api'||$until>0)&&(!$until||$until>time());}
function nma_ready(){ $o=nma_opts();if(empty($o['sales'])||!nma_config_ready($o))return false;if(nma_provider($o)==='square_api'&&nmsa_config($o)['environment']==='sandbox'&&!current_user_can('manage_options'))return false;return true; }
function nma_square_manual_access(){
 if(!current_user_can('manage_options'))return 'Accès refusé.';
 check_admin_referer('nma_square_access');
 $action=sanitize_key($_POST['access_action']??'');$uid=absint($_POST['member_id']??0);$user=$uid?get_user_by('id',$uid):false;
 $email=sanitize_email(wp_unslash($_POST['member_email']??''));$pid=trim(sanitize_text_field(wp_unslash($_POST['square_payment_id']??'')));
 $amount=nma_money_cents(wp_unslash($_POST['square_amount']??''));$currency=sanitize_text_field(wp_unslash($_POST['square_currency']??''));$note=sanitize_textarea_field(wp_unslash($_POST['square_audit_note']??''));
 if(!in_array($action,array('grant','revoke'),true)||!$user||!is_email($email)||strcasecmp($user->user_email,$email)!==0)return 'Le numéro du membre et son courriel doivent désigner le même compte WordPress existant.';
 if(!preg_match('/^[A-Za-z0-9_-]{6,192}$/D',$pid)||$amount<=0||$currency!=='CAD'||$note==='')return 'Indiquez la référence de paiement Square, le montant positif en CAD et une note de vérification.';
 if(empty($_POST['square_attested']))return 'La vérification effective dans Square doit être attestée avant cette opération.';
 $lock='nma_access_lock_'.$uid;if(!add_option($lock,time(),'','no'))return 'Une opération sur cet accès est déjà en cours. Réessayez ; si ce message persiste, contactez l’administrateur.';
 try{
  wp_cache_delete($uid,'user_meta');
  $key='nma_square_payment_'.hash('sha256',$pid);$record=get_option($key,false);$provider=get_user_meta($uid,'nma_payment_provider',true);$active=get_user_meta($uid,'nma_paid',true)==='yes';
  if($provider==='square_api'||get_user_meta($uid,'nmsa_checkout',true))return 'Ce compte dépend du parcours Square API. Utilisez sa réconciliation dédiée.';
  if($record&&(int)($record['uid']??0)!==$uid)return 'Cette référence Square est déjà réservée à un autre membre. Aucune modification effectuée.';
  if($record&&((int)($record['amount_cents']??0)!==$amount||($record['currency']??'')!=='CAD'))return 'Le montant ou la devise diffère du registre de cette référence Square.';
  if($action==='grant'){
   $o=nma_opts();if(nma_provider($o)!=='square_manual'||!nma_config_ready($o))return 'Complétez et vérifiez la configuration Square avant d’attribuer un accès.';
   if($active)return 'Ce membre possède déjà un accès actif. Aucun accès ni paiement supplémentaire n’a été attribué.';
   if($amount!==(int)$o['square_total_cents'])return 'Le montant vérifié doit correspondre exactement au total Square configuré. Aucune modification effectuée.';
   if($record&&($record['status']??'')==='revoked')return 'Cette référence a été révoquée. Elle ne peut pas réactiver un accès ; utilisez une nouvelle référence de paiement vérifiée.';
   if(!$record){$record=array('uid'=>$uid,'payment_id'=>$pid,'amount_cents'=>$amount,'currency'=>'CAD','status'=>'reserved','created_at'=>gmdate('c'));if(!add_option($key,$record,'','no'))return 'Cette référence est en cours d’attribution. Rechargez la page avant de recommencer.';}
   $started=(int)($record['access_started']??time());$until=nma_calendar_access_end($started);$record['access_started']=$started;$record['access_until']=$until;update_user_meta($uid,'nma_access_started',$started);update_user_meta($uid,'nma_access_until',$until);if((int)get_user_meta($uid,'nma_access_until',true)!==$until)return 'Impossible d’enregistrer la durée d’accès.';
   update_user_meta($uid,'nma_payment_provider','square_manual');update_user_meta($uid,'nma_square_payment_id',$pid);update_user_meta($uid,'nma_paid','yes');$record['status']='active';
  }else{
   if(!$record||$provider!=='square_manual'||get_user_meta($uid,'nma_square_payment_id',true)!==$pid)return 'La révocation doit concerner la référence Square actuellement rattachée à ce membre.';
   update_user_meta($uid,'nma_paid','revoked');$record['status']='revoked';
  }
  $audit=array('at'=>gmdate('c'),'administrator_id'=>get_current_user_id(),'member_id'=>$uid,'action'=>$action,'payment_id'=>$pid,'amount_cents'=>$amount,'currency'=>'CAD','attestation'=>$action==='grant'?'Square COMPLETED, article, total et bénéficiaire vérifiés':'Motif de révocation et référence vérifiés dans Square','note'=>$note);
  $record['updated_at']=$audit['at'];update_option($key,$record,false);add_user_meta($uid,'nma_square_access_audit',$audit,false);
  return $action==='grant'?'Accès activé manuellement et vérification enregistrée. Aucun paiement n’a été déclenché.':'Accès révoqué et opération enregistrée. Aucun remboursement n’a été déclenché : il se traite séparément dans Square.';
 }finally{delete_option($lock);}
}
add_action('admin_menu',function(){add_management_page('Neomoov Academy','Neomoov Academy','manage_options','neomoov-academy','nma_admin');});
function nma_admin(){
 if(!current_user_can('manage_options'))return;$o=nma_opts();$clean=nma_clean_stripe_credentials($o);if($clean!==$o){$o=$clean;update_option('nma_settings',$o,false);}$notice='';
 if($_SERVER['REQUEST_METHOD']==='POST'){
  if(($_POST['nma_admin_action']??'')==='square_access'){$notice=nma_square_manual_access();}
  elseif(($_POST['nma_admin_action']??'')==='square_api_reconcile'){$notice=nmsa_admin_reconcile();}
  elseif(($_POST['nma_admin_action']??'')==='square_api_connection'){$notice=nmsa_admin_connection();}
  elseif(($_POST['nma_admin_action']??'')==='brevo_sync'){$notice=nma_brevo_admin_sync();}
  elseif(($_POST['nma_admin_action']??'')==='brevo_connection'){$notice=nma_brevo_admin_connection();}
  elseif(($_POST['nma_admin_action']??'')==='brevo_templates'){$notice=nmbt_admin_import();}
  elseif(($_POST['nma_admin_action']??'')==='brevo_sender_migration'){$notice=nmbt_admin_migrate_sender();}
  else{
   check_admin_referer('nma_settings');
   $o['provider']=sanitize_key($_POST['provider']??'');$o['provider']=nma_provider($o);
   if(nma_provider($o)==='stripe')foreach(array('stripe_key','stripe_price','stripe_hook')as$k){$candidate=isset($_POST[$k])&&is_string($_POST[$k])?sanitize_text_field(wp_unslash($_POST[$k])):'';if(nma_stripe_credential_valid($k,$candidate))$o[$k]=$candidate;}
   if(nma_provider($o)==='square_api')$o=nmsa_save_settings($o);
   $o=nma_brevo_save_settings($o);
   $o=nma_clean_stripe_credentials($o);
   if(isset($_POST['brevo_key'])&&is_string($_POST['brevo_key'])&&trim($_POST['brevo_key'])!=='')$o['brevo_key']=sanitize_text_field(wp_unslash($_POST['brevo_key']));
   foreach(array('brevo_list','square_tax_text','square_access_delay')as$k)$o[$k]=sanitize_text_field(wp_unslash($_POST[$k]??''));
   foreach(array('terms','square_url')as$k)$o[$k]=esc_url_raw(wp_unslash($_POST[$k]??''),array('https'));
   $o['square_price_cents']=nma_money_cents(wp_unslash($_POST['square_price']??''));$o['square_total_cents']=nma_money_cents(wp_unslash($_POST['square_total']??''));
   $requested=!empty($_POST['sales']);$o['sales']=$requested&&nma_config_ready($o);update_option('nma_settings',$o,false);
   $notice=$requested&&!$o['sales']?'Réglages enregistrés. Les ventes restent fermées : complétez tous les paramètres valides du prestataire choisi.':'Réglages enregistrés. '.($o['sales']?'Les ventes sont ouvertes selon le mode choisi.':'Les ventes restent fermées.');
  }
 }
 echo '<div class="wrap"><h1>Neomoov Academy</h1>';if($notice!=='')echo '<div class="notice notice-info"><p>'.esc_html($notice).'</p></div>';
 echo '<p>Pages et outils : <a href="'.esc_url(nma_url()).'">/academy/</a>. Trois modes distincts : Square manuel utilise un lien du Tableau de bord et une attribution humaine ; Square API crée une commande individuelle, vérifie le paiement et traite les notifications signées, avec revue humaine si la facturation est incomplète ; Stripe utilise son checkout et son webhook. Seuls les paramètres du mode choisi sont affichés.</p><form method="post" autocomplete="off">';wp_nonce_field('nma_settings');echo '<input type="hidden" name="nma_admin_action" value="settings"><table class="form-table"><tr><th><label for="provider">Prestataire</label></th><td><select id="provider" name="provider">';
 foreach(array(''=>'Non configuré — ventes fermées','square_manual'=>'Square — activation manuelle','square_api'=>'Square API — commande individuelle Québec','stripe'=>'Stripe — intégration existante')as$k=>$label)echo '<option value="'.esc_attr($k).'" '.selected(nma_provider($o),$k,false).'>'.esc_html($label).'</option>';
 echo '</select><p>Pour configurer les champs privés Stripe ou Square API, sélectionnez ce prestataire puis enregistrez une première fois : ses champs apparaîtront ensuite.</p></td></tr>';
 $fields=array('terms'=>'URL HTTPS des conditions de vente validées','square_url'=>'Lien de paiement Square du Tableau de bord','square_price'=>'Prix de la formation en CAD','square_total'=>'Total exact à payer en CAD','square_tax_text'=>'Mention précise des taxes affichée au client','square_access_delay'=>'Délai et conditions d’activation manuelle choisis par Neomoov','stripe_key'=>'Clé secrète Stripe (mode Stripe uniquement)','stripe_price'=>'ID du prix Stripe en CAD (price_…)','stripe_hook'=>'Secret de signature du webhook Stripe','brevo_key'=>'Clé API Brevo (optionnelle)','brevo_list'=>'ID de liste Brevo (optionnel)');
 foreach($fields as$k=>$label){if(in_array($k,array('brevo_key','brevo_list'),true))continue;$stripe_field=strpos($k,'stripe_')===0;if($stripe_field&&nma_provider($o)!=='stripe')continue;$secret=in_array($k,array('stripe_key','stripe_hook','brevo_key'),true);$value=$secret?'':($o[$k]??'');if(in_array($k,array('square_price','square_total'),true))$value=!empty($o[$k.'_cents'])?number_format($o[$k.'_cents']/100,2,'.',''):'';if(strpos($k,'square_')===0&&nma_provider($o)!=='square_manual'){echo '<input type="hidden" name="'.esc_attr($k).'" value="'.esc_attr($value).'">';continue;}echo '<tr><th><label for="'.esc_attr($k).'">'.esc_html($label).'</label></th><td><input id="'.esc_attr($k).'" name="'.esc_attr($k).'" type="'.($secret?'password':'text').'" class="regular-text" autocomplete="'.(($secret||$stripe_field)?'new-password':'off').'" value="'.esc_attr($value).'">';if($secret&&!empty($o[$k]))echo '<p>Déjà configuré. Laisser vide pour conserver.</p>';echo '</td></tr>';}
 if(nma_provider($o)==='square_api')nmsa_admin_fields($o);
 nma_brevo_admin_fields($o);
 echo '</table>';if(nma_provider($o)==='square_manual')echo '<p>Square manuel : seuls les liens HTTPS de square.link et checkout.square.site sont acceptés. Prix, total, mention fiscale, délai d’accès et conditions sont obligatoires. Vérifiez que le total du lien correspond exactement au total annoncé, sans pourboire ni quantité modifiable. Aucune clé API Square n’est utilisée dans ce mode.</p>';echo '<p>Avant ouverture : vendeur légal, contenu réellement livré, durée d’accès, politique de remboursement, fiscalité et parcours de paiement vérifiés. Le délai annoncé doit être tenu ; surveillez les paiements et remboursements chez le prestataire choisi.</p>';if(nma_provider($o)==='stripe')echo '<p>Webhook Stripe : <code>'.esc_html(rest_url('neomoov-academy/v1/stripe')).'</code>.</p>';echo '<label><input type="checkbox" name="sales" value="1" '.checked(!empty($o['sales']),true,false).'> Ouvrir les ventes après vérification</label>';submit_button('Enregistrer les réglages');echo '</form><hr><details'.(nma_provider($o)==='square_manual'?' open':'').'><summary>Mode Square manuel — attribution et révocation humaines</summary><h2>Accès Square manuel</h2><p>Cette opération modifie seulement l’accès à la formation. Avant activation, ouvrez le paiement dans Square et vérifiez son statut COMPLETED, Neomoov Chauffeur Pro, le total en CAD et le membre bénéficiaire. Une capture transmise par le client ou un retour vers le site ne suffit pas.</p><form method="post">';wp_nonce_field('nma_square_access');echo '<input type="hidden" name="nma_admin_action" value="square_access"><table class="form-table">';
 foreach(array('member_id'=>'ID du compte membre WordPress','member_email'=>'Courriel du même compte membre','square_payment_id'=>'Référence exacte du paiement Square','square_amount'=>'Montant du paiement vérifié en CAD')as$k=>$label)echo '<tr><th><label for="'.esc_attr($k).'">'.esc_html($label).'</label></th><td><input id="'.esc_attr($k).'" name="'.esc_attr($k).'" type="'.($k==='member_email'?'email':'text').'" class="regular-text" required autocomplete="off"></td></tr>';
 echo '<tr><th>Devise vérifiée</th><td><select name="square_currency"><option value="CAD">CAD — dollar canadien</option></select></td></tr><tr><th>Opération</th><td><select name="access_action"><option value="grant">Activer après paiement COMPLETED vérifié</option><option value="revoke">Révoquer après vérification du motif dans Square</option></select></td></tr><tr><th><label for="square_audit_note">Note de vérification / motif</label></th><td><textarea id="square_audit_note" name="square_audit_note" rows="3" class="large-text" required maxlength="2000"></textarea></td></tr></table><label><input type="checkbox" name="square_attested" value="1" required> J’atteste avoir contrôlé la référence dans Square. Pour une activation : paiement COMPLETED, article, montant en CAD et bénéficiaire vérifiés. Pour une révocation : motif et référence vérifiés.</label>';submit_button('Enregistrer l’opération manuelle');echo '</form></details><hr><h2>Journal des opérations Square manuelles</h2><form method="get"><input type="hidden" name="page" value="neomoov-academy"><label>ID du membre <input type="number" name="audit_member" min="1" required></label> <button class="button">Consulter</button></form>';
 $audit_uid=absint($_GET['audit_member']??0);if($audit_uid&&get_user_by('id',$audit_uid)){$audit=get_user_meta($audit_uid,'nma_square_access_audit',false);echo '<p>Compte #'.esc_html($audit_uid).' · état : '.esc_html(get_user_meta($audit_uid,'nma_paid',true)?:'gratuit').' · prestataire : '.esc_html(get_user_meta($audit_uid,'nma_payment_provider',true)?:'aucun').'</p>';if(!$audit)echo '<p>Aucune opération Square enregistrée.</p>';else{echo '<table class="widefat"><thead><tr><th>UTC</th><th>Administrateur</th><th>Opération</th><th>Référence</th><th>Montant</th><th>Vérification</th></tr></thead><tbody>';foreach(array_reverse($audit)as$a)if(is_array($a))echo '<tr><td>'.esc_html($a['at']??'').'</td><td>'.esc_html($a['administrator_id']??'').'</td><td>'.esc_html($a['action']??'').'</td><td>'.esc_html($a['payment_id']??'').'</td><td>'.esc_html(nma_money($a['amount_cents']??0)).'</td><td>'.esc_html(($a['attestation']??'').' — '.($a['note']??'')).'</td></tr>';echo '</tbody></table>';}}
 if(function_exists('nmsa_admin_status'))nmsa_admin_status();
 nma_brevo_admin_status();
 nmbt_admin_status();
 echo '</div>';
}
function nma_stripe($path,$body=null,$idempotency=''){
 $o=nma_opts();$args=array('timeout'=>25,'headers'=>array('Authorization'=>'Bearer '.($o['stripe_key']??'')));
 if($body!==null){$args['method']='POST';$args['body']=$body;if($idempotency!=='')$args['headers']['Idempotency-Key']=$idempotency;}
 $r=wp_remote_request('https://api.stripe.com/v1/'.$path,$args);
 if(is_wp_error($r)||wp_remote_retrieve_response_code($r)<200||wp_remote_retrieve_response_code($r)>=300)return new WP_Error('stripe','Le service de paiement est temporairement indisponible.');
 $data=json_decode(wp_remote_retrieve_body($r),true);return is_array($data)?$data:new WP_Error('stripe','Réponse de paiement invalide.');
}
add_action('rest_api_init',function(){register_rest_route('neomoov-academy/v1','/stripe',array('methods'=>'POST','permission_callback'=>'__return_true','callback'=>'nma_webhook'));});
function nma_webhook($r){$o=nma_opts();$secret=$o['stripe_hook']??'';$raw=$r->get_body();if(!$secret||strlen($raw)>1048576)return new WP_REST_Response(null,400);$ts=0;$signatures=array();foreach(explode(',',$r->get_header('stripe-signature'))as$p){$kv=explode('=',$p,2);if(count($kv)!==2)continue;if($kv[0]==='t')$ts=(int)$kv[1];if($kv[0]==='v1')$signatures[]=$kv[1];}if(abs(time()-$ts)>300)return new WP_REST_Response(null,400);$expected=hash_hmac('sha256',$ts.'.'.$raw,$secret);$valid=false;foreach($signatures as$s)if(hash_equals($expected,$s))$valid=true;if(!$valid)return new WP_REST_Response(null,400);$event=json_decode($raw,true);$obj=$event['data']['object']??array();$type=$event['type']??'';
 if(in_array($type,array('checkout.session.completed','checkout.session.async_payment_succeeded'),true)){
  $id=$obj['id']??'';if(!is_string($id)||!preg_match('/^cs_[A-Za-z0-9_]+$/',$id))return new WP_REST_Response(null,400);
  $s=nma_stripe('checkout/sessions/'.$id.'?expand[]=line_items&expand[]=payment_intent.latest_charge');if(is_wp_error($s))return new WP_REST_Response(null,503);
  $uid=(int)($s['client_reference_id']??0);$items=$s['line_items']['data']??array();$price=$items[0]['price']??array();$pi=$s['payment_intent']??array();$charge=is_array($pi)?($pi['latest_charge']??array()):array();$pid=is_array($pi)?($pi['id']??''):'';
  $match=count($items)===1&&($price['id']??'')===($o['stripe_price']??'')&&(int)($items[0]['quantity']??0)===1&&($price['type']??'')==='one_time'&&(int)($price['unit_amount']??0)===9900&&($price['currency']??'')==='cad';
  if($uid&&get_user_by('id',$uid)&&$match&&($s['mode']??'')==='payment'&&($s['payment_status']??'')==='paid'&&($s['currency']??'')==='cad'&&($s['metadata']['academy']??'')==='cap-chauffeur'){
   $access_lock='nma_access_lock_'.$uid;if(!add_option($access_lock,time(),'','no'))return new WP_REST_Response(null,503);
   try{
   wp_cache_delete($uid,'user_meta');
   if(in_array(get_user_meta($uid,'nma_payment_provider',true),array('square_manual','square_api'),true)||get_user_meta($uid,'nmsa_checkout',true))return new WP_REST_Response(array('received'=>true),200);
   if(!preg_match('/^pi_[A-Za-z0-9_]+$/',$pid)||!is_array($charge)||empty($charge['id']))return new WP_REST_Response(null,503);
   $refund_key='nma_refunded_'.hash('sha256',$pid);
   if(!empty($charge['refunded']))update_option($refund_key,true,false);
   if(get_option($refund_key,false)||!empty($charge['refunded'])){
    if(get_user_meta($uid,'nma_payment_intent',true)===$pid)update_user_meta($uid,'nma_paid','refunded');
   }elseif(($pi['status']??'')==='succeeded'&&!empty($charge['paid'])){
    $same_payment=get_user_meta($uid,'nma_payment_intent',true)===$pid;$started=$same_payment?(int)get_user_meta($uid,'nma_access_started',true):0;if(!$started&&!($same_payment&&get_user_meta($uid,'nma_paid',true)==='yes'))$started=time();if($started){update_user_meta($uid,'nma_access_started',$started);update_user_meta($uid,'nma_access_until',nma_calendar_access_end($started));}
    update_user_meta($uid,'nma_payment_provider','stripe');update_user_meta($uid,'nma_payment_intent',$pid);update_user_meta($uid,'nma_session',$id);update_user_meta($uid,'nma_paid','yes');
    // Bypass this request's option cache so a concurrent refund can win.
    wp_cache_delete($refund_key,'options');wp_cache_delete('notoptions','options');
    if(get_option($refund_key,false))update_user_meta($uid,'nma_paid','refunded');
   }
   }finally{delete_option($access_lock);}
  }
 }
 if($type==='charge.refunded'&&!empty($obj['refunded'])&&!empty($obj['payment_intent'])){
  $pid=$obj['payment_intent'];if(!is_string($pid)||!preg_match('/^pi_[A-Za-z0-9_]+$/',$pid))return new WP_REST_Response(null,400);
  update_option('nma_refunded_'.hash('sha256',$pid),true,false);
  foreach(get_users(array('meta_key'=>'nma_payment_intent','meta_value'=>$pid,'fields'=>'ID'))as$uid){$access_lock='nma_access_lock_'.$uid;if(!add_option($access_lock,time(),'','no'))return new WP_REST_Response(null,503);try{wp_cache_delete($uid,'user_meta');if(!in_array(get_user_meta($uid,'nma_payment_provider',true),array('square_manual','square_api'),true)&&!get_user_meta($uid,'nmsa_checkout',true)&&get_user_meta($uid,'nma_payment_intent',true)===$pid)update_user_meta($uid,'nma_paid','refunded');}finally{delete_option($access_lock);}}
 }return new WP_REST_Response(array('received'=>true),200);}
function nma_post(){if($_SERVER['REQUEST_METHOD']!=='POST')return '';if(!isset($_POST['nma_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['nma_nonce'])),'nma_action'))return 'Votre session a expiré. Actualisez puis réessayez.';$act=sanitize_key($_POST['nma_action']??'');
 if($act==='join'){$email=sanitize_email(wp_unslash($_POST['email']??''));$name=sanitize_text_field(wp_unslash($_POST['name']??''));$track=sanitize_key($_POST['track']??'rentabilite');if(!is_email($email)||!$name||!empty($_POST['website']))return 'Vérifiez votre nom et votre email.';$rate='nma_'.hash_hmac('sha256',($_SERVER['REMOTE_ADDR']??''),wp_salt());$count=(int)get_transient($rate);if($count>=5)return 'Veuillez patienter avant une nouvelle demande.';set_transient($rate,$count+1,HOUR_IN_SECONDS);if(!email_exists($email)){$uid=wp_insert_user(array('user_login'=>'academy_'.wp_generate_password(16,false),'user_email'=>$email,'user_pass'=>wp_generate_password(32,true),'display_name'=>$name,'role'=>'subscriber'));if(is_wp_error($uid))return 'Inscription indisponible. Contactez contact@neomoov.net.';update_user_meta($uid,'nma_track',array_key_exists($track,nma_tracks())?$track:'rentabilite');update_user_meta($uid,'nma_consent',!empty($_POST['consent'])?'yes':'no');update_user_meta($uid,'nma_consent_date',gmdate('c'));wp_new_user_notification($uid,null,'user');}return 'Demande reçue. Si votre compte vient d’être créé, consultez votre email pour définir votre mot de passe. Si vous avez déjà un compte, connectez-vous ou utilisez « Mot de passe oublié ». Aucun paiement n’a été effectué.';}
 if(!is_user_logged_in())return 'Connectez-vous pour continuer.';$uid=get_current_user_id();if($act==='unsubscribe'){update_user_meta($uid,'nma_consent','no');return 'Votre consentement aux emails commerciaux a été retiré.';}
 if($act==='quiz'||$act==='attestation')return nma_formation_post($act,$uid);
 if($act==='balance'){$v=array();foreach(array('receipts','costs','hours','km')as$k){$raw=str_replace(',','.',wp_unslash($_POST[$k]??''));if(!is_numeric($raw)||(float)$raw<0||(float)$raw>10000000)return 'Vérifiez les valeurs saisies.';$v[$k]=(float)$raw;}if($v['hours']<=0||$v['km']<=0)return 'Les heures et kilomètres doivent être supérieurs à zéro.';$v['date']=gmdate('c');$items=(array)get_user_meta($uid,'nma_balances',true);array_unshift($items,$v);update_user_meta($uid,'nma_balances',array_slice($items,0,100));return 'Bilan enregistré dans votre espace membre.';}
 if($act==='checkout'){
  if(get_user_meta($uid,'nma_paid',true)==='yes')return 'Votre accès est déjà actif. Aucun nouveau paiement n’est nécessaire.';
  if(!nma_ready())return 'Les paiements ne sont pas encore ouverts.';if(empty($_POST['accept']))return 'Veuillez lire et accepter les conditions de vente.';
  $o=nma_opts();
  if(nma_provider($o)==='square_api')return 'Utilisez le formulaire Square API dédié dans votre espace.';
  if(get_user_meta($uid,'nmsa_checkout',true)||get_user_meta($uid,'nma_payment_provider',true)==='square_api')return 'Un achat Square API est déjà associé à ce compte. Contactez le support.';
  if(nma_provider($o)==='square_manual'){
   if(!nma_square_url($o['square_url']??''))return 'Le lien de paiement Square doit être vérifié.';
   $manual_lock='nma_access_lock_'.$uid;if(!add_option($manual_lock,time(),'','no'))return 'Une demande de paiement est déjà en cours.';
   try{wp_cache_delete($uid,'user_meta');if(get_user_meta($uid,'nmsa_checkout',true)||get_user_meta($uid,'nma_paid',true)==='yes')return 'Un achat est déjà associé à ce compte. Contactez le support avant de payer.';
   add_user_meta($uid,'nma_square_checkout_notice',array('at'=>gmdate('c'),'terms'=>$o['terms'],'price_cents'=>(int)$o['square_price_cents'],'total_cents'=>(int)$o['square_total_cents'],'tax_text'=>$o['square_tax_text'],'access_delay'=>$o['square_access_delay']),false);
   }finally{delete_option($manual_lock);}
   wp_redirect($o['square_url'],303);exit;
  }
  if(nma_provider($o)!=='stripe')return 'Le prestataire de paiement doit être configuré.';
  if(get_user_meta($uid,'nma_payment_provider',true)==='square_manual')return 'Votre compte possède un historique de paiement Square. Avant tout nouveau paiement, contactez contact@neomoov.net pour vérifier votre accès. Aucun paiement Stripe n’a été créé.';
  $price_id=$o['stripe_price'];if(!preg_match('/^price_[A-Za-z0-9_]+$/',$price_id))return 'Le prix de la formation doit être vérifié.';
  $price=nma_stripe('prices/'.$price_id);if(is_wp_error($price))return 'Impossible de vérifier le prix. Réessayez plus tard.';
  if(empty($price['active'])||($price['type']??'')!=='one_time'||($price['currency']??'')!=='cad'||(int)($price['unit_amount']??0)!==9900)return 'Le prix de la formation doit être un paiement unique actif de 99 $ CA.';
  $lock='nma_access_lock_'.$uid;
