   $saved=(array)get_user_meta($uid,'nma_checkout',true);$s=null;
   if(!empty($saved['id'])&&preg_match('/^cs_[A-Za-z0-9_]+$/',$saved['id'])){
    $prior=nma_stripe('checkout/sessions/'.$saved['id'].'?expand[]=line_items');if(is_wp_error($prior))return 'Impossible de vérifier votre paiement en cours. Réessayez plus tard.';
    if((int)($prior['client_reference_id']??0)!==$uid||($prior['metadata']['academy']??'')!=='cap-chauffeur')return 'Votre session de paiement doit être vérifiée.';
    if(($prior['status']??'')==='complete')return get_user_meta($uid,'nma_paid',true)==='refunded'?'Votre précédent paiement a été remboursé. Contactez-nous pour une nouvelle inscription.':'Votre paiement est en cours de confirmation. Aucun nouveau paiement n’est nécessaire.';
    if(($prior['status']??'')==='open'){
     $lines=$prior['line_items']['data']??array();if(count($lines)!==1||($lines[0]['price']['id']??'')!==$price_id||(int)($lines[0]['quantity']??0)!==1)return 'Un autre paiement est déjà ouvert. Contactez-nous avant de recommencer.';
     if(($prior['currency']??'')!=='cad'||(int)($prior['amount_subtotal']??0)!==9900||($prior['mode']??'')!=='payment')return 'Votre session de paiement doit être vérifiée.';
     $s=$prior;
    }elseif(($prior['status']??'')!=='expired')return 'Votre paiement est en cours de vérification.';
   }
   if(!$s){
