    if(is_wp_error($s))return 'Le service de paiement ne répond pas. Réessayez.';
    if(($s['status']??'')!=='open'||empty($s['id']))return 'Votre paiement est en cours de confirmation. Aucun nouveau paiement n’est nécessaire.';
    update_user_meta($uid,'nma_checkout',array('id'=>$s['id'],'price'=>$price_id));
