function nma_sales($track){$tracks=nma_tracks();$t=$tracks[$track]??null;$hero=nma_hero_img();echo '<section class="hero wrap"><div><p class="eyebrow">NEOMOOV ACADEMY · MONTRÉAL · TAXI & VTC</p><p class="edition">Neomoov Chauffeur Pro / 7 modules, quiz et attestation de suivi</p><h1>'.($t?nma_e($t[1]):'Prenez les commandes<br>de votre <em>activité.</em>').'</h1><p class="lead">'.($t?nma_e($t[2]):'Mieux organiser vos journées. Soigner chaque trajet. Comprendre ce qui vous reste. Des méthodes de terrain et des outils pour avancer.').'</p><div class="actions"><a class="btn" href="'.esc_url(nma_url('inscription/?parcours='.($track?:'rentabilite'))).'">Commencer gratuitement</a><a class="text-link" href="#programme">Explorer la formation</a></div><p class="small">Formation complémentaire · Essence & électrique · Français</p></div><div class="hero-visual">';echo $hero;echo '<div class="visual-caption"><span>LA MÉTHODE NEOMOOV</span><strong>Du terrain.<br>Des outils.<br>Un cap.</strong></div></div></section><div class="band"><div class="wrap band-inner"><span>01 / Votre temps</span><span>02 / Votre service</span><span>03 / Vos résultats</span></div></div><section class="wrap section"><p class="eyebrow">VOTRE PROCHAIN CAP</p><h2>'.($t?nma_e($t[3]):'Un métier. Plusieurs façons d’avancer.').'</h2>';
 if($t){echo '<ol class="steps">';foreach($t[4]as$s)echo '<li>'.nma_e($s).'</li>';echo '</ol><p>Commencez par une observation de votre quotidien. Choisissez une amélioration concrète, puis comparez vos résultats avant de modifier votre organisation.</p>';}else{echo '<div class="track-grid">';$i=0;foreach($tracks as$slug=>$v)echo '<a class="track-card" href="'.esc_url(nma_url($slug.'/')).'"><span class="index">0'.(++$i).'</span><h3>'.nma_e($v[0]).'</h3><p>'.nma_e($v[1]).'</p><span class="text-link">Découvrir mon parcours</span></a>';echo '</div>'; }echo '</section><section class="section dark"><div class="wrap two-col"><div><p class="eyebrow">UNE MÉTHODE APPLICABLE</p><h2>Les bonnes décisions commencent par les bonnes observations.</h2><p>Conçu à partir de l’expérience de terrain de notre fondateur, chauffeur et exploitant à Montréal, et des difficultés rapportées par des chauffeurs et des passagers.</p></div><div class="principles"><article><b>Mesurer</b><p>Compter toutes les heures et tous les kilomètres de la journée.</p></article><article><b>Améliorer</b><p>Choisir une action utile au client, réalisable dans votre quotidien.</p></article><article><b>Comparer</b><p>Évaluer vos changements sur vos propres données.</p></article></div></div></section><section class="wrap section" id="programme"><p class="eyebrow">LE PROGRAMME Neomoov Chauffeur Pro</p><h2>7 modules pour exercer en règle, en sécurité et avec de meilleurs résultats.</h2><p>Chaque module comprend un exercice corrigé, un quiz de 5 questions et ses sources officielles. Les 7 quiz réussis donnent droit à une attestation de suivi vérifiable par code. L’offre de lancement comprend aussi 8 fiches pratiques et l’application Neomoov Booster en version web. Accès pendant 12 mois calendaires à compter de l’activation. Les vidéos ne sont pas incluses dans cette offre.</p><div class="module-list">';$i=0;foreach(nma_modules()as$k=>$v)echo '<article><span class="index">0'.(++$i).'</span><h3>'.nma_e($k).'</h3><p>'.nma_e($v).'</p></article>';echo '</div><p class="small">Formation complémentaire : aucun permis délivré, aucune équivalence avec la formation obligatoire au Québec. Aucun revenu garanti.</p></section><section class="section pale"><div class="wrap two-col"><div><p class="eyebrow">NEOMOOV BOOSTER</p><h2>Moins d’approximations.<br>Plus de repères.</h2><p>L’application qui accompagne la formation : bilan de journée, fiche de vérification du véhicule avant départ et plan d’amélioration de l’habitacle.</p><a class="btn" href="'.esc_url(nma_url('booster/')).'">Ouvrir Neomoov Booster</a><p class="small">Version web, gratuite avec votre espace. Versions Android et iPhone en préparation.</p></div><div class="tool-preview"><span>VOTRE PROCHAINE SESSION</span><h3>Prêt avant le premier client.</h3><p>Vérification avant départ consignée</p><p>Habitacle dégagé, kit à portée</p><p>Point de rencontre confirmé</p><p>Temps et frais suivis</p></div></div></section><section class="wrap section two-col"><div><p class="eyebrow">COMMENCEZ AUJOURD’HUI</p><h2>Un premier pas utile,<br>sans engagement.</h2><p>Les ressources gratuites vous aident à tester la méthode et à préparer votre prochaine session.</p><a class="btn" href="'.esc_url(nma_url('inscription/?parcours='.($track?:'rentabilite'))).'">Créer mon espace gratuit</a></div><div class="offer-card"><p class="eyebrow">Neomoov Chauffeur Pro</p>';nma_offer_pricing();echo '<ul><li>7 modules écrits avec exercices corrigés et quiz</li><li>Attestation de suivi vérifiable par code</li><li>8 fiches pratiques imprimables</li><li>Neomoov Booster, version web</li><li>Accès formation pendant 12 mois calendaires</li><li>Offre de lancement écrite : vidéos non incluses</li></ul><p>'.(nma_ready()?'Consultez les conditions et le montant total avant de payer.':'Paiements en cours de préparation. Vous pouvez déjà vous inscrire gratuitement.').'</p><a class="btn" href="'.esc_url(nma_url('membre/')).'">Mon espace formation</a><p><a href="https://neomoov.net/conditions-cap-chauffeur/">Conditions de vente Neomoov Chauffeur Pro</a></p></div></section><section class="wrap section">'.nma_join_neomoov().'</section><section class="wrap section faq"><h2>Un cadre clair dès le départ.</h2><details><summary>À qui s’adresse cette formation ?</summary><p>Chauffeurs taxi et VTC, futurs chauffeurs, exploitants et futurs investisseurs. Un guide gratuit est dédié aux passagers.</p></details><details><summary>Que puis-je utiliser maintenant ?</summary><p>Neomoov Booster en version web, les 8 fiches pratiques et l’espace gratuit sont accessibles. L’offre Neomoov Chauffeur Pro donne accès pendant 12 mois calendaires après activation aux 7 modules écrits, avec exercices corrigés, quiz et attestation de suivi. Les vidéos ne sont pas incluses.</p></details><details><summary>Est-ce un diagnostic mécanique ?</summary><p>Non. Les conseils concernent propreté, rangement, confort et précautions visibles. L’outil ne certifie pas la conformité et ne remplace pas un professionnel.</p></details><details><summary>Les photos sont-elles analysées automatiquement ?</summary><p>Cette version permet une auto-observation assistée par vos photos. Les recommandations sont calculées à partir de vos réponses au questionnaire. Les photos ne quittent pas votre navigateur.</p></details><details><summary>Qu’est-ce que l’attestation de suivi ?</summary><p>Elle est délivrée quand les 7 quiz sont réussis, avec au moins 4 bonnes réponses sur 5 par module. Elle porte un code que toute personne, un employeur ou un opérateur par exemple, peut vérifier sur <a class="text-link" href="'.esc_url(nma_url('attestation/')).'">la page de vérification</a>. Elle ne remplace aucun permis, aucune formation obligatoire et aucune certification.</p></details><details><summary>La formation permet-elle de rouler avec Neomoov ?</summary><p>Neomoov, plateforme 100 % électrique, sélectionne ses chauffeurs : dossier en règle, véhicule électrique admissible et niveau de service. L’attestation Neomoov Chauffeur Pro est un atout dans votre candidature, sans garantie d’admission ni de courses.</p></details></section>';}
function nma_companion(){echo '<div class="wrap section"><p class="eyebrow">NEOMOOV BOOSTER</p><h1>Votre activité, plus claire.</h1><p>L’application de la formation Neomoov Chauffeur Pro, en version web. À utiliser à l’arrêt. Les données du bilan ne sont conservées que si vous choisissez de les enregistrer dans votre compte ; la fiche de vérification reste sur votre appareil.</p><nav class="toc no-print" aria-label="Outils de Neomoov Booster"><a href="#bilan">Bilan de journée</a><a href="#verification">Vérification avant départ</a><a href="#habitacle">Plan d’amélioration du véhicule</a></nav><section class="panel" id="bilan"><h2>Comptez toute votre journée.</h2><p>Recettes après commissions de plateforme et hors taxes collectées. Dépenses attribuées à la même période, sans déduire une seconde fois les commissions déjà retirées.</p><form method="post" id="nma-bilan">';nma_nonce('balance');echo '<div class="form-grid">';foreach(array('receipts'=>'Recettes après commissions ($ CA)','costs'=>'Dépenses d’exploitation ($ CA)','hours'=>'Toutes les heures d’activité','km'=>'Tous les kilomètres professionnels')as$k=>$label)echo '<label class="field">'.$label.'<input type="number" name="'.$k.'" min="'.(in_array($k,array('hours','km'))?'0.01':'0').'" step="0.01" required></label>';echo '</div><p class="small">Incluez énergie, entretien, assurance, location ou amortissement et autres dépenses attribuées à la période. Les heures comprennent approche, attente, recharge et repositionnement.</p><div class="result" id="nma-result" aria-live="polite">Complétez les quatre champs.</div><p class="small">Estimation d’exploitation avant impôt personnel, dépendante de l’exhaustivité de vos données. Aucun revenu futur garanti.</p><div class="actions"><button type="button" class="btn secondary" onclick="window.print()">Imprimer / PDF</button>';if(is_user_logged_in())echo '<button class="btn">Enregistrer mon bilan</button>';else echo '<a class="btn" href="'.esc_url(nma_url('membre/')).'">Me connecter pour enregistrer</a>';echo '</div></form></section>';nma_check_sheet();echo '<section class="panel" id="habitacle"><h2>Votre plan d’amélioration du véhicule.</h2><p>Photographiez l’habitacle, le coffre et les rangements sans visage, plaque ou document personnel. Observez vos photos puis cochez les points déjà satisfaisants. Les recommandations reposent sur vos réponses : aucune analyse automatique d’image ni diagnostic mécanique.</p><label class="field">Photos de référence (4 maximum, JPEG / PNG / WebP, 8 Mo par image)<input id="nma-photos" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><p class="small">Vos photos restent dans votre navigateur pendant cette session et ne sont pas téléversées.</p><p id="nma-photo-message" role="status"></p><div id="nma-photo-preview" class="photo-grid"></div><div id="nma-checks">';foreach(array('Sol et espace passager dégagés','Objets fixés sans gêner les airbags','Visibilité et commandes dégagées','Câbles en bon état et rangés','Habitacle propre et surfaces nettoyées','Coffre disponible pour les bagages','Absence d’odeur gênante après aération','Documents utiles accessibles')as$c)echo '<label class="check-row"><input type="checkbox" value="'.esc_attr($c).'">'.nma_e($c).'</label>';echo '</div><label class="field">Motorisation<select id="nma-motor"><option value="essence">Essence / hybride</option><option value="electrique">Électrique</option></select></label><div class="actions"><button class="btn" type="button" id="nma-plan-button">Afficher mes priorités</button></div><div id="nma-plan" aria-live="polite"></div><p>Cette liste ne prouve pas la conformité du véhicule. Toute anomalie ou tout doute sur la sécurité nécessite l’avis d’un professionnel qualifié.</p></section></div>';}
function nma_resources($passenger=false){$data=nma_data();echo '<section class="wrap section"><p class="eyebrow">LES FICHES NEOMOOV</p><h1>'.($passenger?'Une prise en charge plus sereine.':'Des outils à emporter sur le terrain.').'</h1><p>Fiches de démarrage gratuites, à lire et imprimer. Elles ne remplacent pas les vérifications réglementaires ni un avis professionnel.</p><button class="btn no-print" onclick="window.print()">Imprimer / Enregistrer en PDF</button><div class="resource-grid" style="margin-top:30px">';foreach(($data['resources']??array())as$r){if($passenger&&$r['id']!=='guide-passagers')continue;echo '<article id="'.esc_attr($r['id']).'"><h2>'.nma_e($r['title']).'</h2><p>'.nma_e($r['intro']).'</p><ol>';foreach($r['steps']as$s)echo '<li>'.nma_e($s).'</li>';echo '</ol><h3>À vous de jouer</h3><p>'.nma_e($r['exercise']).'</p><p><b>Exemple :</b> '.nma_e($r['example']).'</p></article>'; }echo '</div></section>';}
function nma_member($training=false){echo '<section class="wrap section"><p class="eyebrow">VOTRE ESPACE NEOMOOV</p><h1>'.($training?'Votre parcours Neomoov Chauffeur Pro.':'Bienvenue à bord.').'</h1>';if(!is_user_logged_in()){echo '<div class="panel"><h2>Connectez-vous à votre compte.</h2><a class="btn" href="'.esc_url(wp_login_url(nma_url($training?'formation/':'membre/'))).'">Me connecter</a> <a class="text-link" href="'.esc_url(wp_lostpassword_url(nma_url('membre/'))).'">Mot de passe oublié</a><p><a href="'.esc_url(nma_url('inscription/')).'">Créer mon espace gratuit</a></p></div></section>';return;}$uid=get_current_user_id();$paid=nma_has_access($uid);echo '<p>'.nma_e(wp_get_current_user()->display_name).' · <a href="'.esc_url(wp_logout_url(nma_url())).'">Me déconnecter</a></p>';if($training){if(!$paid&&!current_user_can('manage_options')){echo '<div class="panel"><h2>Accès réservé aux membres de la formation.</h2><p>Votre espace gratuit reste disponible. L’accès au programme s’active après un paiement confirmé lorsque les ventes sont ouvertes.</p><a class="btn" href="'.esc_url(nma_url('membre/')).'">Revenir à mon espace</a></div>';}else{echo '<p>Votre offre de lancement écrite : 7 modules avec exercices corrigés, quiz et attestation de suivi, 8 fiches pratiques et l’application Neomoov Booster. Accès pendant 12 mois calendaires à compter de l’activation. Les vidéos ne sont pas incluses.</p>';if(current_user_can('manage_options')&&!$paid)echo '<p class="message">Aperçu administrateur : aucun paiement n’est associé à cet accès.</p>';nma_formation($uid);}echo '</section>';return;}
 echo '<div class="resource-grid"><div class="panel"><h2>Neomoov Booster</h2><p>Bilan de journée, fiche de vérification avant départ et plan d’amélioration du véhicule.</p><a class="btn" href="'.esc_url(nma_url('booster/')).'">Ouvrir Neomoov Booster</a><p><a href="'.esc_url(nma_url('ressources/')).'">Mes fiches imprimables</a></p></div><div class="panel"><h2>Neomoov Chauffeur Pro</h2>';if($paid){list($done,$total)=nma_progress($uid);echo '<p>Votre accès formation est actif. Progression : '.$done.' / '.$total.' modules réussis.</p><a class="btn" href="'.esc_url(nma_url('formation/')).'">Ouvrir la formation</a>';if($total&&$done===$total)echo '<p><a class="text-link" href="'.esc_url(nma_url('attestation/')).'">Mon attestation de suivi</a></p>';}elseif(nma_ready()){nma_checkout_form(nma_opts());}else echo '<p>Les paiements sont en préparation. Vos ressources gratuites sont accessibles dès maintenant.</p>';echo '</div></div><h2>Mes derniers bilans</h2>';$items=(array)get_user_meta($uid,'nma_balances',true);if(!$items)echo '<p>Aucun bilan enregistré.</p>';else{echo '<div class="module-list">';foreach(array_slice($items,0,30)as$b)if(is_array($b))echo '<article><span>•</span><h3>'.nma_e(substr($b['date'],0,10)).'</h3><p>'.number_format($b['receipts']-$b['costs'],2,',',' ').' $ CA · '.nma_e($b['hours']).' h · '.nma_e($b['km']).' km</p></article>';echo '</div>';}if(function_exists('nmsa_member_status'))nmsa_member_status($uid);echo '<form method="post">';nma_nonce('unsubscribe');echo '<button class="text-link">Retirer mon consentement aux emails commerciaux</button></form><p class="small">Pour une copie ou une suppression des données : contact@neomoov.net.</p></section>';}
function nma_privacy(){echo '<section class="wrap section narrow"><h1>Vos données dans Neomoov Academy</h1><p>Contact : Neomoov, 204 rue du Saint-Sacrement, Montréal (Québec), contact@neomoov.net.</p><h2>Compte et outils</h2><p>Votre prénom, votre adresse email et les informations techniques nécessaires à votre connexion permettent de créer et sécuriser votre compte WordPress. Les bilans sont enregistrés uniquement sur votre demande et sont rattachés à votre compte. Les photos de Neomoov Booster restent dans votre navigateur et ne sont pas transmises à Neomoov ; la fiche de vérification avant départ n’est pas enregistrée par Neomoov.</p><h2>Quiz et attestation</h2><p>Vos réponses aux quiz et vos résultats sont enregistrés dans votre compte pour suivre votre progression. L’attestation de suivi conserve le nom que vous indiquez, la date de réussite et un code de vérification. Pour un code exact, la page publique de vérification n’affiche que votre prénom, l’initiale de votre nom et la date de réussite.</p><h2>Communications</h2><p>L’inscription gratuite n’exige pas d’accepter les emails commerciaux. Votre choix et sa date sont enregistrés. Vous pouvez retirer votre consentement depuis votre espace ou le lien de désinscription des emails. Si vous acceptez les conseils et offres, votre adresse email et votre parcours pourront être transmis à Brevo après votre première connexion au compte. Brevo gère les listes et les désinscriptions pour Neomoov. Les acheteurs sont retirés des listes de relance de cette offre. Les messages nécessaires à la création du compte et à votre achat restent distincts des offres commerciales.</p><h2>Accès et conservation</h2><p>L’accès aux données du compte est limité à vous et aux administrateurs habilités. Les données sont conservées pour fournir le service, traiter vos demandes et satisfaire les obligations applicables. Vous pouvez demander accès, correction ou suppression à contact@neomoov.net ; les pièces devant être conservées légalement peuvent faire exception.</p><h2>Paiement</h2><p>'.esc_html(nma_payment_privacy()).'</p><p>Consultez également la <a href="'.esc_url(home_url('/politique-de-confidentialite/')).'">politique de confidentialité du site</a> et ses coordonnées complètes.</p></section>';}
function nma_style(){return <<<'CSS'
__ACADEMY_CSS__
CSS;
}
function nma_script(){return <<<'JS'
(()=>{const f=document.getElementById('nma-bilan');if(f){const result=document.getElementById('nma-result');f.addEventListener('input',()=>{const keys=['receipts','costs','hours','km'];const inputs=keys.map(k=>f.elements.namedItem(k));const v=inputs.map(e=>Number(e.value));if(inputs.some(e=>e.value==='')||v.some(x=>!Number.isFinite(x)||x<0)||v[2]<=0||v[3]<=0){result.textContent='Complétez les quatre champs avec des heures et kilomètres supérieurs à zéro.';return}const m=v[0]-v[1];result.textContent='Résultat estimé : '+m.toFixed(2)+' $ CA — '+(m/v[2]).toFixed(2)+' $ CA/heure — '+(m/v[3]).toFixed(2)+' $ CA/km. Avant impôt personnel.';});}const photos=document.getElementById('nma-photos');if(photos)photos.addEventListener('change',()=>{const preview=document.getElementById('nma-photo-preview');preview.replaceChildren();const files=Array.from(photos.files||[]).slice(0,4).filter(f=>['image/jpeg','image/png','image/webp'].includes(f.type)&&f.size<=8*1024*1024);document.getElementById('nma-photo-message').textContent=files.length+' photo(s) retenue(s). Maximum 4 images, 8 Mo par image.';files.forEach((file,i)=>{const reader=new FileReader();reader.onload=()=>{const img=document.createElement('img');img.src=String(reader.result);img.alt='Photo de référence '+(i+1);preview.append(img)};reader.readAsDataURL(file)});});const b=document.getElementById('nma-plan-button');if(b)b.addEventListener('click',()=>{const out=document.getElementById('nma-plan');out.className='result';out.replaceChildren();const h=document.createElement('h3');h.textContent='Vos priorités selon vos observations';out.append(h);const list=document.createElement('ol');const missing=Array.from(document.querySelectorAll('#nma-checks input')).filter(e=>!e.checked);missing.forEach(e=>{const li=document.createElement('li');li.textContent=e.value+' : à améliorer avant la prochaine prise en charge.';list.append(li)});out.append(list);if(!missing.length){const p=document.createElement('p');p.textContent='Vous avez confirmé tous les points. Maintenez cette routine ; cela ne constitue pas une validation de conformité.';out.append(p)}const p=document.createElement('p');p.textContent=document.getElementById('nma-motor').value==='electrique'?'Préparez la recharge selon votre trajet et les consignes du constructeur. Comptabilisez son coût et le temps d’arrêt. Ne touchez pas aux composants haute tension.':'Préparez le ravitaillement et suivez les consignes d’entretien du constructeur. Un témoin ou une anomalie nécessite une vérification adaptée.';out.append(p);const print=document.createElement('button');print.className='btn secondary';print.textContent='Imprimer mon plan';print.onclick=()=>window.print();out.append(print)});})();
(()=>{const now=new Date(),p=n=>String(n).padStart(2,'0');document.querySelectorAll('input[data-now]').forEach(i=>{if(!i.value)i.value=now.getFullYear()+'-'+p(now.getMonth()+1)+'-'+p(now.getDate())+'T'+p(now.getHours())+':'+p(now.getMinutes())});document.querySelectorAll('[data-print]').forEach(b=>b.addEventListener('click',()=>{const t=document.getElementById(b.dataset.print);if(!t)return;t.querySelectorAll('details').forEach(d=>{d.open=true});document.body.classList.add('nma-print-one');t.classList.add('nma-print-target');window.print()}));window.addEventListener('afterprint',()=>{document.body.classList.remove('nma-print-one');document.querySelectorAll('.nma-print-target').forEach(e=>e.classList.remove('nma-print-target'))});})();
JS;
}
/* Pages publiques : cache du serveur LWS pour les visiteurs anonymes (les membres connectés le contournent) ; jamais de cache de page de l'extension LWS Optimize. Le serveur ignore la durée demandée : vider avec la route cache/purge après chaque déploiement. */
function nma_public_routes(){return array('','rentabilite','service','demarrer','entreprise','booster','ressources','passagers','confidentialite','attestation');}
function nma_cache_headers($page){if(!defined('DONOTCACHEPAGE'))define('DONOTCACHEPAGE',true);if(in_array($page,nma_public_routes(),true)&&!is_user_logged_in()&&($_SERVER['REQUEST_METHOD']??'GET')==='GET'&&empty($_GET)){header('Cache-Control: public, max-age=0, s-maxage=600');return;}nocache_headers();}
add_action('rest_api_init',function(){register_rest_route('neomoov-academy/v1','/cache/purge',array('methods'=>'POST','permission_callback'=>function(){return current_user_can('manage_options');},'callback'=>function(){$out=array();foreach(array_merge(nma_public_routes(),array('chauffeur-pro','compagnon')) as $p){$r=wp_remote_request(nma_url($p===''?'':$p.'/'),array('method'=>'PURGE','timeout'=>8));$out['/academy/'.($p===''?'':$p.'/')]=is_wp_error($r)?'erreur':(int)wp_remote_retrieve_response_code($r);}return new WP_REST_Response(array('purge'=>$out),200);}));});
add_action('template_redirect',function(){ $path=trim((string)wp_parse_url($_SERVER['REQUEST_URI']??'',PHP_URL_PATH),'/');if($path!=='academy'&&strpos($path,'academy/')!==0)return;$page=trim(substr($path,7),'/');$allowed=array('','rentabilite','service','demarrer','entreprise','inscription','compagnon','chauffeur-pro','booster','attestation','ressources','passagers','membre','formation','confidentialite');if(!in_array($page,$allowed,true))return;if($page==='compagnon'||$page==='chauffeur-pro'){wp_safe_redirect(nma_url('booster/'),301);exit;}nma_cache_headers($page);$message=nma_post();status_header(200);header('Content-Type: text/html; charset=UTF-8');$tracks=nma_tracks();list($title,$description)=nma_seo($page,$tracks);echo '<!doctype html><html lang="fr-CA"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.esc_html($title).'</title><meta name="description" content="'.esc_attr($description).'"><link rel="canonical" href="'.esc_url(nma_url($page?$page.'/':'')).'">';if(in_array($page,array('membre','formation','inscription','attestation'),true))echo '<meta name="robots" content="noindex,nofollow">';echo '<style>'.nma_style().'</style></head><body><header class="wrap header"><a class="brand" href="'.esc_url(nma_url()).'">neomoov<span>ACADEMY</span></a><nav aria-label="Navigation principale"><a href="'.esc_url(nma_url('#programme')).'">La formation</a><a href="'.esc_url(nma_url('booster/')).'">Neomoov Booster</a><a href="'.esc_url(nma_url('ressources/')).'">Ressources</a><a class="nav-member" href="'.esc_url(nma_url('membre/')).'">Mon espace</a></nav></header><main>';if($message)echo '<div class="wrap message" role="status">'.nma_e($message).'</div>';if($page===''||isset($tracks[$page]))nma_sales($page);elseif($page==='booster')nma_companion();elseif($page==='attestation')nma_attestation_page();elseif($page==='ressources'||$page==='passagers')nma_resources($page==='passagers');elseif($page==='membre'||$page==='formation')nma_member($page==='formation');elseif($page==='confidentialite')nma_privacy();elseif($page==='inscription'){$t=sanitize_key($_GET['parcours']??'rentabilite');if(!isset($tracks[$t]))$t='rentabilite';echo '<section class="wrap section narrow"><p class="eyebrow">VOTRE PREMIER PAS</p><h1>'.nma_e($tracks[$t][3]).'</h1><p>Fiches pratiques, outils web et bilans personnels. Inscription gratuite, aucun paiement.</p>';if(is_user_logged_in())echo '<a class="btn" href="'.esc_url(nma_url('membre/')).'">Ouvrir mon espace</a>';else nma_form_join($t);echo '</section>';}echo '</main><footer><div class="wrap footer-inner"><a class="brand" href="'.esc_url(nma_url()).'">neomoov<span>ACADEMY</span></a><p>Des méthodes de terrain pour avancer.</p><nav><a href="'.esc_url(nma_url('attestation/')).'">Vérifier une attestation</a><a href="'.esc_url(nma_url('passagers/')).'">Pour les passagers</a><a href="'.esc_url(nma_url('confidentialite/')).'">Confidentialité</a><a href="'.esc_url(home_url('/mentions-legales/')).'">Mentions légales</a><a href="https://neomoov.net/conditions-cap-chauffeur/">Conditions de vente</a><a href="mailto:contact@neomoov.net">Contact</a></nav><small>© 2026 Neomoov Academy · Montréal</small></div></footer><script>'.nma_script().'</script></body></html>';exit;},0);
